document.addEventListener("DOMContentLoaded",function(){var e=document.querySelectorAll(".faq-question");0<e.length&&(e.forEach(e=>{e.addEventListener("click",function(){var e,t,n=this.parentElement;n&&(e=n.classList.contains("active"),t=n.querySelector(".faq-answer"),e?(n.classList.remove("active"),t&&(t.style.maxHeight=null)):(n.classList.add("active"),t&&(t.style.maxHeight=t.scrollHeight+"px")))})}),e[0].click(),window.addEventListener("resize",function(){document.querySelectorAll(".faq-item.active .faq-answer").forEach(e=>{e.style.maxHeight="none",e.style.maxHeight=e.scrollHeight+"px"})}),window.addEventListener("load",function(){window.dispatchEvent(new Event("resize"))}))});